    static let quadWreckDeathV1 = SmallCases.make(
        key: "story.quadWreckDeath",
        category: .traffic,
        headlines: ["Side-by-Side Rolls on Hay Field Slope, Rider Killed", "Phone Video Shows Wild Ride Before Rollover"],
        law: "misdDBV",
        threshold: 6,
        spec: "Unintentionally killed {V} while driving an off-road vehicle in violation of a safety statute, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "On {DATE}, {D} took {V} for a ride in a side-by-side utility vehicle across a steep hay field. The vehicle rolled on a slope and {V} was crushed beneath the roll bar. {V} was not buckled in. A phone video {V} was taking shows the ride beforehand. {DL} says the grass was wet and the vehicle slid.",
        state: [E(.video, 3, "Rider's Phone Video", "The vehicle slams over ruts at high speed as {V} laughs and yells to slow down."), E(.physical, 3, "The Side-by-Side", "The speed limiter plug is unplugged and the seat belts are tucked behind the seats.", .search)],
        defense: [E(.statement, 2, "Wet Grass", "{DL} says a rain shower soaked the slope that afternoon.")],
        role: "Highway patrol reconstructionist",
        exam: [.direct("What did you find on the side-by-side?", "\"The speed limiter plug was unplugged, and the seat belts were tucked behind the seats. Both were visible when I examined the machine.\""), .direct("What does the speed limiter do?", "\"It caps the machine's top speed. With the plug disconnected, the machine can go much faster than it was built to.\""), .direct("What did the phone video show?", "\"A fast ride over bumps, with the passenger asking to slow down. {V} is laughing and yelling for the driver to stop.\""), .direct("Where did the rollover happen?", "\"On a steep hay field, on a slope. The machine slid, rolled, and came to rest on its side.\""), .direct("What killed {V}?", "\"{V} was crushed beneath the roll bar. {V} was not buckled in, and the belts were out of reach behind the seats.\""), .direct("What was the ground like?", "\"Damp at the bottom of the slope, with short wet grass. I measured the incline and found it steeper than the manual allows.\""), .cross("Was the grass wet?", "\"Damp at the bottom, yes. Wet grass reduces traction, and I include it in my analysis.\""), .cross("Can you give an exact speed?", "\"Only a range. I can say the machine was going faster than the limiter would normally allow, and nothing more precise.\""), .cross("Can you tell who unplugged the limiter?", "\"No. I can only tell it was unplugged. I cannot tell you when or by whom.\""), .cross("Did {D} cooperate with you?", "\"Yes. {D} showed me where the ride started and answered my questions.\""), .cross("Could a machine slide on a wet slope even at a moderate speed?", "\"Yes. Wet grass on a steep slope can send a machine sliding, even at a modest speed.\"")],
        theory: ("{D} drove fast with the safety gear disabled and {V} died.", "A wet slope caused the slide."),
        allocution: "\"I keep seeing that slope.\"",
        truths: ("{DL} unplugged the limiter weeks earlier to go faster.", "A farmhand had unplugged the limiter to haul a load and never told {DL}."),
        defendant: [.direct("Were you racing?", "\"No. We were just cruising. {V} wanted to see the field, and I took it easy until the bumps.\""), .direct("Why were there no belts on?", "\"They were stuck behind the seats. I did not notice, and neither did {V}, until it was too late.\""), .direct("What about the video?", "\"We were bouncing, that is all. {V} was laughing, and I thought it was fun for both of us.\""), .direct("What about the limiter?", "\"I never touched it. I did not know it was unplugged, and I never took it apart.\""), .direct("What happened on the slope?", "\"The grass was wet, and the machine slid sideways. I tried to steer out of it, and it rolled.\""), .direct("How do you feel about {V}'s death?", "\"I am heartbroken. {V} was my friend, and I will carry what happened in that field every day.\""), .cross("You were driving, weren't you?", "\"Yes. I was driving, and I take responsibility for that.\""), .cross("{V} asked you to slow down, didn't {V.he}?", "\"On the video, yes. I thought we were fine, and I should have listened.\""), .cross("The seat belts were tucked behind the seats, weren't they?", "\"Yes. I did not look for them. I should have checked before driving.\""), .cross("The speed limiter was unplugged, wasn't it?", "\"So I am told. I did not unplug it, and I did not know.\""), .cross("You drove across a steep slope with damp grass, didn't you?", "\"Yes. I did, and it was a bad choice.\"")],
        openings: ("{D} took {V} for a ride in a side-by-side across a steep hay field, and the machine rolled and crushed {V} beneath the roll bar. The speed limiter was unplugged, the belts were tucked behind the seats, and {V}'s phone video shows a fast ride with {V} asking to slow down.", "The grass was wet, the slope was steep, and the machine slid. {D} never touched the limiter and did not know the belts were stuck behind the seats."),
        closings: ("An unplugged speed limiter, belts out of reach, and a passenger on video asking to slow down. {V} died because {D} drove too fast.", "A wet slope, a machine that slid, and a limiter {D} says was never touched. A terrible accident is not a crime unless the State proves recklessness."),
        timeline: [(0, "2 p.m.: the ride begins."), (0, "2:40 p.m.: a shower soaks the field."), (0, "3 p.m.: the rollover on the slope."), (0, "3:25 p.m.: deputies arrive.")],
        identified: "The driver stayed at the scene.",
        mood: .sympathetic)

    static let dogMaulingV1 = SmallCases.make(
        key: "story.dogMauling",
        category: .violent,
        headlines: ["Jogger Killed by Dogs Loosed From Backyard Pen", "Owner Faces Murder Charge After Fence Complaints"],
        law: "murder2",
        threshold: 10,
        spec: "Unlawfully and with malice killed {V} by keeping dogs {D.he} knew to be dangerous in a pen {D.he} knew was unsecured.",
        ages: 44...50,
        victim: true,
        summary: "On {DATE}, {V}, 33, was jogging on a rural road when three large dogs broke out of a pen behind {D}'s house and attacked {V.him}. {V} was bitten more than sixty times and died at the roadside. Neighbors had complained for two years that the dogs got out. The pen latch was a loop of wire. A mail carrier had been chased the month before. {DL} says {D.he} ran out and fought the dogs off and had just fixed the fence.",
        state: [E(.document, 3, "Complaint File", "Twenty-two complaints, a citation for loose dogs, and a letter from the county warning of a dangerous-dog hearing."), E(.forensic, 3, "Autopsy", "More than sixty bite wounds and blood loss from torn arteries."), E(.physical, 2, "Wire Latch", "The pen latch was a twisted wire loop that a child could open."), E(.statement, 2, "Mail Carrier", "The carrier says {DL} laughed after a chase and said the dogs were harmless.")],
        defense: [E(.forensic, 2, "Defendant's Wounds", "Bite wounds on {DL}'s forearms and a torn shirt."), E(.document, 1, "Fence Receipt", "A receipt for new fencing bought the week before.")],
        role: "Animal control supervisor",
        exam: [.direct("What had {D} been told about the dogs?", "\"Citations, and a notice of a dangerous-dog hearing. The county's letter warned that the dogs could be declared dangerous.\""), .direct("How many complaints were on file?", "\"Twenty-two complaints over two years, and a citation for loose dogs. Neighbors reported the dogs getting out repeatedly.\""), .direct("What was the pen like?", "\"A wire loop for a latch, and a gap under the panel. The loop was a twisted piece of wire that a child could open.\""), .direct("What did the autopsy find?", "\"More than sixty bite wounds and blood loss from torn arteries. {V} died at the roadside, jogging.\""), .direct("Did the defendant get bitten?", "\"Yes, on the arms. {D} ran out and fought the dogs and was injured doing it.\""), .direct("Did the defendant buy a new fence?", "\"The boards were stacked, not installed. They were stacked beside the pen when we arrived.\""), .cross("Did the defendant try to stop the dogs?", "\"Yes. {DL} ran out and fought them, and {DL} was hurt on both arms.\""), .cross("Did the defendant call for help?", "\"Yes. {D.He} called 911 and stayed with {V} until help arrived.\""), .cross("Were the dogs aggressive toward {D}?", "\"Not toward {D.him}. They turned on {V}, who was a stranger on the road.\""), .cross("Did anyone see how they got out?", "\"No. No one saw how they got out that morning.\""), .cross("Had a dog bitten a person before?", "\"A mail carrier was chased the month before. I do not have a bite report.\"")],
        defenseRole: "Farrier",
        defenseExam: [.direct("What do you do?", "\"I am a farrier. I shoe horses and visit farms in the area, including {D}'s.\""), .direct("How did the dogs act around {D}?", "\"Gentle. They followed {DF} around, wagged their tails, and listened to commands.\""), .direct("How did they act around you?", "\"Loud at the fence, but friendly when I stepped in. They sniffed me and settled down.\""), .direct("Did you ever see them loose?", "\"Twice. Once on the road, once in the yard, and both times {DF} called them back right away.\""), .direct("Did you tell the defendant?", "\"I did. I told {DF} the gate needed a better latch, and {DF} said {D.he} would fix it.\""), .direct("What did you think of the pen?", "\"Rough. It was sturdy enough for years, but the gate was a weak point.\""), .cross("Did you see the fence repaired?", "\"Boards were stacked by the pen. I did not see them installed.\""), .cross("Did you ever see the dogs bite anyone?", "\"Never. They were loud, and they never bit me.\""), .cross("Did neighbors complain to you?", "\"A few did. I told {D.him}.\""), .cross("Were the dogs large?", "\"Yes. They were big dogs, with a lot of strength, and I understand why neighbors were afraid.\""), .cross("Are you friends with the defendant?", "\"I have known {DF} for years. I only know what I saw on those visits.\"")],
        theory: ("{D} ignored two years of warnings and left killer dogs behind a wire latch.", "A tragic escape by a caring owner who tried to stop it."),
        allocution: "\"I would trade places if I could.\"",
        truths: ("{DL} had been bragging to friends that the dogs would get any trespasser.", "A delivery driver propped the pen gate open that morning and left without closing it."),
        defendant: [.direct("How did the dogs get out?", "\"I do not know. The gate was shut when I checked that morning, and I went inside.\""), .direct("Were the dogs dangerous?", "\"They were big and loud, not mean. They never hurt anyone in all the years I had them.\""), .direct("What about the twenty-two complaints?", "\"Neighbors exaggerate. A dog barking at a fence becomes a complaint, and I tried to answer each one.\""), .direct("What about the wire latch?", "\"It held for years. I used it every day, and it never failed until that morning.\""), .direct("What did you do when the dogs attacked?", "\"I ran out and fought them off. I got bitten on both arms, and I called 911.\""), .direct("What do you want {V}'s family to know?", "\"I am so sorry. I loved those dogs, and I never imagined they could do this to anyone.\""), .cross("The county warned you about a dangerous-dog hearing, didn't it?", "\"Yes. I got the letter, and I meant to fix the fence.\""), .cross("The boards were stacked and not installed, weren't they?", "\"Yes. I had just bought them, and I was about to put them up.\""), .cross("A mail carrier was chased the month before, wasn't one?", "\"So I heard. I did not see it.\""), .cross("A child could open that latch, couldn't a child?", "\"Maybe so. It held for years.\""), .cross("{V} was bitten more than sixty times, wasn't {V.he}?", "\"Yes. I will never forget it.\"")],
        openings: ("{V}, 33, was jogging on a rural road when three large dogs broke out of a pen behind {D}'s house and killed {V.him}. Neighbors had complained for two years, the pen latch was a loop of wire, and the county had warned {D} of a dangerous-dog hearing.", "{D} ran out, fought the dogs off, and had just bought boards to fix the fence. The gate was shut when {D} checked, and the dogs had never bitten anyone."),
        closings: ("Twenty-two complaints, a citation, a county warning, a wire latch, and sixty bites. {D} knew these dogs were a danger and did not fix the pen.", "A gate {D} says was shut, a fence about to be repaired, and gentle dogs by every account. The State must prove {D} was reckless, not unlucky."),
        timeline: [(-730, "First complaint about loose dogs."), (-30, "Mail carrier chased and cited."), (0, "Morning: the pen gate is found open."), (0, "5:40 p.m.: the attack on the road.")],
        identified: "{DL} was at the scene and the dogs were {D.his}.",
        aggravating: ["The offense was especially heinous, atrocious, or cruel"],
        mitigating: ["No prior criminal record"],
        mood: .wantsConviction,
        impact: "{V} was out for a run on a road {V.he} knew by heart.",
        doctrines: ["burdenOfProof", "lesserIncluded"],
        genders: ["D": .female, "V": .female])

    static let bloodTestStartupV1 = SmallCases.make(
        key: "story.bloodTestStartup",
        category: .whiteCollar,
        headlines: ["Skin Patch Founder Accused of Faking Glucose Data", "Investors Say the Patch Never Read Blood Sugar"],
        law: "securitiesFraud",
        threshold: 8,
        spec: "In the offer and sale of securities, made untrue statements of material fact to {V} and other North Carolina investors.",
        ages: 29...42,
        victim: true,
        summary: "{D} ran a startup selling a wearable patch said to track blood sugar without needles. Investors, including {V}, a retired pharmacist, put in nine million dollars. A former lab manager says test numbers shown to investors came from a finger-prick meter hidden in the demo room. A university study the deck cited was never finished. {DL} says the lab team promised the patch was nearly ready.",
        state: [E(.document, 3, "Pitch Deck", "A slide claims a completed university trial with 97 percent accuracy. The university says the study never ended."), E(.statement, 3, "Lab Manager", "The manager says demo readings were copied by hand from a hidden meter."), E(.digital, 2, "Founder Texts", "{DL} writes: \"Keep the meter behind the screen during tours.\""), E(.document, 2, "Wire Records", "Investor money paid down {DL}'s personal credit lines.")],
        defense: [E(.document, 2, "Lab Reports", "Weekly reports from the science lead rating accuracy at 90 percent."), E(.document, 2, "Salary Records", "{DL} took a modest salary and put in personal savings."), E(.statement, 1, "Venture Fund", "A professional fund did its own review and invested.")],
        role: "Former lab manager",
        exam: [.direct("What did the patch do?", "\"It gave noise. We never matched a real glucose meter, and the readings were random most of the time.\""), .direct("What happened at investor demos?", "\"I copied numbers from a hidden meter onto the screen. A finger-prick meter sat behind the display in the demo room.\""), .direct("Who gave you those orders?", "\"The science lead said it was temporary. I was told it would be fixed as soon as the patch was ready.\""), .direct("Did {D} write the numbers?", "\"No. I did. I copied them by hand from the hidden meter, and I wrote them on the screen.\""), .direct("What did the pitch deck claim?", "\"A completed university trial with 97 percent accuracy. The university later told me the study never ended.\""), .direct("What did the defendant write to you?", "\"'Keep the meter behind the screen during tours.' I have the message, and I saved it.\""), .cross("Did the defendant ever see you copy numbers?", "\"I do not know. {D} was in the building during tours, and I cannot say what {D.he} saw.\""), .cross("Did the team believe the patch would work?", "\"Some did. The science lead kept telling us we were close.\""), .cross("Did the defendant hire you?", "\"Yes. {DL} was a demanding boss, but never asked me directly to fake data.\""), .cross("Why did you stay?", "\"I believed the patch would work. I kept hoping it would.\""), .cross("Did you tell anyone?", "\"Not until I left. I was afraid and ashamed.\"")],
        defenseRole: "Venture analyst",
        defenseExam: [.direct("What is your work?", "\"I am a venture analyst. I evaluate startups for funds and review the claims founders make.\""), .direct("What do founders promise?", "\"The future, often. Founders promise what they hope to deliver, and investors are expected to discount that.\""), .direct("Did you see the hidden meter?", "\"Never. I saw demos and decks, and nothing about a meter behind a screen.\""), .direct("Would that change your view?", "\"Completely. A hidden meter is a different matter from an optimistic pitch.\""), .direct("How is optimism different from fraud?", "\"A founder who believes the product will work is optimistic. A founder who knows it does not and says it does is lying.\""), .direct("Did you evaluate {D}'s company?", "\"I reviewed the deck. I did not invest, and I was cautious about the trial claim.\""), .cross("Did you check the university trial?", "\"No. I did not call the university. I should have, and I did not.\""), .cross("Would a fake demo mislead an investor?", "\"Yes. It would be a serious deception.\""), .cross("Did you speak with the defendant?", "\"Briefly, at a conference. {D} was confident.\""), .cross("Do you know what happened to the investor money?", "\"Only what I have read. I would not guess.\""), .cross("Are you paid by either side?", "\"I am paid for my time, as in any case.\"")],
        theory: ("{D} sold a patch that did not work by hiding a meter behind the screen.", "A founder misled by the science team."),
        allocution: "\"I wanted it to work so badly.\"",
        truths: ("{DL} paid off personal credit lines with the investor funds.", "The science lead admitted writing fake accuracy numbers into the weekly reports."),
        defendant: [.direct("Did you believe it worked?", "\"I did. The lab team told me the patch was nearly ready, and I believed them.\""), .direct("What about the trial slide?", "\"The university said the study was underway. I put that on the slide, and I did not realize it had not finished.\""), .direct("What about the text about the meter?", "\"Protecting trade secrets. I did not want visitors to see our reference equipment and copy our approach.\""), .direct("What about the credit lines?", "\"I paid them after I put in my own money. I lent the company my savings first, and I took some back.\""), .direct("What did {V} invest?", "\"A large share of the nine million. {V} trusted me, and I am so sorry.\""), .direct("What do you want the investors to know?", "\"I never meant to deceive anyone. I thought we were close, and I was wrong.\""), .cross("The slide said the study was complete, didn't it?", "\"It said completed. I believed the university's progress report.\""), .cross("You wrote 'Keep the meter behind the screen during tours,' didn't you?", "\"Yes. I did not think of it as deceiving anyone.\""), .cross("A hidden meter fed the demo numbers, didn't it?", "\"So the lab manager says. I did not know the numbers were copied.\""), .cross("You paid off personal credit lines with investor funds, didn't you?", "\"I repaid money I had put in. I see how it looks.\""), .cross("Nine million dollars was raised on those demos, wasn't it?", "\"Yes. I believed in the patch, and so did the investors.\"")],
        openings: ("{D} ran a startup selling a wearable patch said to track blood sugar without needles, and investors including {V}, a retired pharmacist, put in nine million dollars. A former lab manager says demo numbers came from a finger-prick meter hidden in the demo room.", "{D} believed the lab team that the patch was nearly ready. An optimistic founder who overpromises is not a swindler, and {D} lent the company {D.his} own savings."),
        closings: ("A trial slide the university says never ended, a hidden meter, a text about keeping it behind the screen, and investor money used on personal credit. The demo was a show.", "A founder who believed the lab, a slide based on the university's progress, and a reference meter kept private. The State must prove {D} knew the patch did not work."),
        timeline: [(-540, "The company launches and raises seed money."), (-30, "{DL} texts about the hidden meter."), (0, "{V} invests after a lab tour."), (400, "The lab manager quits and calls regulators.")],
        identified: "{DL} led the tours and signed the offering papers.",
        aggravating: ["The offense caused large monetary losses"],
        mitigating: ["No prior criminal record"],
        mood: .wantsConviction,
        impact: "That money was my retirement.")

    static let sellPillsAtWorkV1 = SmallCases.make(
        key: "story.sellPillsAtWork",
        category: .drugs,
        headlines: ["Forklift Driver Accused of Selling Pain Pills in the Parking Lot", "Text Messages Lead to Buy Behind the Loading Dock"],
        law: "deliverSchedII",
        threshold: 6,
