        ages: 24...58,
        victim: false,
        summary: "A plant manager gave deputies the phone of a worker who said {D} had offered pills for sale. On {DATE}, the worker handed {D} four twenty-dollar bills in a parking lot and took home four oxycodone tablets, deputies watching. {DL} says the worker had been begging for relief from a back injury and the money was for gas.",
        state: [E(.video, 3, "Parking Lot Camera", "A hand-off between two parked trucks."), E(.document, 3, "Lab Report", "Four tablets confirmed as oxycodone."), E(.digital, 1, "Text Thread", "\"Got fours. Eighty.\"")],
        defense: [E(.document, 2, "Prescription Bottle", "{DL}'s own bottle for a back injury, filled ten days earlier.")],
        role: "Sheriff's narcotics deputy",
        exam: [.direct("How did this investigation begin?", "\"A plant manager gave us the phone of a worker who said {D} had offered pills for sale. We set up a controlled buy.\""), .direct("What did you watch?", "\"The worker pay and take a small bag. The worker handed {DL} four twenty-dollar bills in a parking lot.\""), .direct("What was in the bag?", "\"Four oxycodone tablets. The lab confirmed it after we took the tablets into evidence.\""), .direct("What does the parking lot camera show?", "\"A hand-off between two parked trucks. The camera shows the exchange of money and a small bag.\""), .direct("What does the text thread say?", "\"'Got fours. Eighty.' The messages set up the meeting in the lot.\""), .direct("Where were you during the buy?", "\"Watching from a distance, with another deputy. We saw the whole exchange and moved in right after.\""), .cross("Did {D} have a prescription?", "\"Yes. {D.He} has a valid prescription for oxycodone, which I confirmed after the arrest.\""), .cross("Did you see the count on that bottle?", "\"No. We did not examine the bottle until later, and I cannot say how many tablets were left.\""), .cross("Who started the contact?", "\"The worker. The worker reached out to {DL} first, according to the phone.\""), .cross("Did the defendant set a price?", "\"The text says 'Eighty.' I cannot say if {D.he} set it or answered a request.\""), .cross("Did the defendant cooperate when arrested?", "\"Yes. {D.He} did not resist and explained the money was for gas.\"")],
        theory: ("{D} sold oxycodone for cash in the parking lot.", "A favor for a hurting coworker, with gas money."),
        allocution: "\"I should have said no.\"",
        truths: ("{DL}'s phone held offers of pills at a set price to two other workers.", "The coworker pressed {DL} for weeks and set up the meeting."),
        defendant: [.direct("What was the money?", "\"Gas. The worker offered to chip in for a ride and gas money after I helped with some pain relief.\""), .direct("Did you price the pills?", "\"No. I did not set a price. The worker handed me money, and I handed over tablets I was prescribed.\""), .direct("What does the text 'Eighty' mean?", "\"A joke. We joke about prices. I did not mean it as a sale.\""), .direct("Why did you meet in the lot?", "\"Away from the boss. We did not want anyone seeing it and thinking the wrong thing.\""), .direct("Why did you give the worker tablets?", "\"The worker had been begging for relief from a back injury. I felt sorry, and I should not have shared.\""), .direct("What do you want the court to know?", "\"I made a poor decision to help a coworker in pain. I did not run a business, and I regret that.\""), .cross("You handed over four oxycodone tablets, didn't you?", "\"Yes, and I should not have. They were mine, prescribed to me.\""), .cross("You took four twenty-dollar bills, didn't you?", "\"Yes. I thought of it as gas money.\""), .cross("You texted 'Got fours. Eighty,' didn't you?", "\"Yes. It was a joke, and I see how it reads.\""), .cross("You met in a parking lot, away from the boss, didn't you?", "\"Yes. I did not want trouble, and I should not have gone.\""), .cross("Sharing a prescription is against the law, isn't it?", "\"I know. I made a mistake, and I am deeply sorry.\"")],
        openings: ("A plant manager gave deputies the phone of a worker who said {D} had offered pills for sale. In a parking lot, deputies watched the worker hand {D} four twenty-dollar bills and take home four oxycodone tablets, and a text read 'Got fours. Eighty.'", "The worker had been begging for relief from a back injury, and {D} gave a few tablets as a favor. The money was for gas, and sharing a prescription out of sympathy is not drug dealing."),
        closings: ("Four twenty-dollar bills, four oxycodone tablets, and a text reading 'Got fours. Eighty.' That exchange in a parking lot was a sale, whatever name {D} gives it.", "A coworker in obvious pain, a valid prescription, and a few dollars for gas. The State must prove {D} sold pills for profit, and {D} gave a favor."),
        timeline: [(-10, "{DL} fills the prescription."), (0, "Morning: the manager hands over the texts."), (0, "Lunch: the buy in the lot.")],
        identified: "A coworker's report and a controlled buy.",
        aggravating: ["The offense involved sale or delivery"],
        mitigating: ["The defendant has a positive employment history and is gainfully employed"],
        mood: .indifferent)

    static let dogHoardingV1 = SmallCases.make(
