        victim: false,
        summary: "On {DATE}, a humane officer followed up on a neighbor's call and found thirty-six dogs in {D}'s mobile home and a tin shed. Water was frozen in the pans. Eight dogs were underweight and two had untreated eye infections; one died within days. {DL} breeds and fosters small dogs. {DL} says a cold snap froze the pans overnight and a sister who helped moved away a month earlier.",
        state: [E(.video, 3, "Officer's Video", "Frozen pans, soiled crates, and thin dogs in the shed."), E(.document, 3, "Vet Exams", "Eight underweight dogs, two with untreated infections, one euthanized."), E(.document, 1, "Notice Letter", "A county letter two months earlier asked {DL} to cut the number of dogs.")],
        defense: [E(.document, 3, "Feed Receipts", "$310 a month in dog food and vet visits."), E(.statement, 2, "Cold Snap", "Overnight lows fell to 14 degrees."), E(.document, 1, "Foster Log", "Nineteen dogs placed in homes last year.")],
        role: "County humane officer",
        exam: [.direct("What did you find at {D}'s property?", "\"Thirty-six dogs in a mobile home and a tin shed. Water in the pans was frozen, and crates were soiled.\""), .direct("What does your video show?", "\"Frozen pans, soiled crates, and thin dogs in the shed. It also shows the cold, because my breath is visible.\""), .direct("How many dogs needed care?", "\"Ten, and one died. Eight were underweight, and two had untreated eye infections.\""), .direct("What did the vet find?", "\"Eight underweight dogs and two untreated infections, and one dog had to be euthanized within days.\""), .direct("Was there a county letter?", "\"Yes. A county letter two months earlier asked {D} to reduce the number of dogs.\""), .direct("What was the temperature that night?", "\"The low was 14. That is cold enough to freeze water pans in a few hours.\""), .cross("Did it freeze overnight?", "\"Yes. The low was 14, and open water pans freeze at that temperature.\""), .cross("Was there food?", "\"Yes, in bins. I saw food, and the dogs had access to it.\""), .cross("Were the dogs clean?", "\"Some were. The crates in the shed were soiled, but the mobile home was cleaner.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} met us at the door and said a sibling who helped had moved away a month earlier.\""), .cross("Did the defendant treat any of the dogs?", "\"{D.He} said so. We found some medication in the home.\"")],
        defenseRole: "Feed store owner",
