        state: [E(.video, 3, "Store Camera", "A runner in a gray hood grabs the phone and shoves {V}."), E(.physical, 3, "The Phone Case", "A case with {V}'s photo inside, found in {DL}'s pocket."), E(.forensic, 1, "Lip Injury", "A cut lip photographed at the scene.")],
        defense: [E(.statement, 1, "Found Case", "{DL} says {D.he} picked it up from the sidewalk.")],
        role: "Responding deputy",
