        ages: 48...52,
        victim: true,
        summary: "On {DATE}, {V}, 13, and a 14-year-old friend were riding bikes on a greenway on a summer afternoon. A doorbell camera near the trailhead recorded a rider on a bike following them. Their bodies were found off the trail the next morning. The case went cold for six years. Then a lab retested a shoelace used to bind a wrist and found DNA. A family tree search led to {D}, a bus mechanic. {DL} says the bike and shoelace were stolen from the garage long ago.",
        state: [E(.forensic, 3, "Shoelace DNA", "DNA on a knotted lace matches {DL} at a very high rate."), E(.video, 3, "Doorbell Camera", "A rider on a green bike trails the teens into the trail."), E(.statement, 3, "Cellmate", "A cellmate says {DL} described the bridge and the knots."), E(.document, 2, "Bike Registration", "A green bike of the same type registered to {DL}.")],
        defense: [E(.forensic, 2, "Contamination", "A defense scientist says low amounts of DNA can transfer by touch."), E(.statement, 2, "Garage Theft", "A neighbor recalls {DL} reporting a garage break-in that year.")],
        role: "Cold case detective",
