        defense: [E(.statement, 2, "Plea Deals", "The teens were offered reduced charges for testifying."), E(.document, 1, "Cut From Team", "A coach's note shows the teen was dropped from the team."), E(.document, 1, "No Prints", "No prints or DNA tie {DL} to the bat.")],
        role: "Lead detective",
        exam: [.direct("How did {D} come to be a suspect?", "\"Two teens confessed and named {D}. A 16-year-old swimmer and a friend said {DL} offered $4,000 and a place to stay.\""), .direct("What did the wire recording capture?", "\"It shows {DL} telling a third teen, 'Say nothing and we are fine.' The teen wore a wire at our request.\""), .direct("What did the defendant do the night of the killing?", "\"Called 911 after a late swim meet, saying {V} was lying on the floor of the garage. {V} was already dead.\""), .direct("How was {V} killed?", "\"Beaten with a bat in the garage of the home {V} shared with {DL}, {V}'s spouse.\""), .direct("What did the bank records show?", "\"$4,000 withdrawn from {D.his} account in the week before the killing.\""), .direct("What did the garage door log show?", "\"A late entry that matches the teen's story. The opener logged an entry about the time the teens said.\""), .cross("Was there physical evidence tying the defendant to the bat?", "\"None. We found nothing tying {DL} to the bat, and the teens' accounts are the heart of the case.\""), .cross("Did the teens get deals?", "\"Yes. Both received favorable treatment in exchange for their statements.\""), .cross("Did the defendant confess?", "\"No. {D.He} has denied any role from the start.\""), .cross("Was there a life insurance policy?", "\"A new $250,000 policy on {V}. The timing was noted, though it does not prove anything.\""), .cross("Did the defendant cooperate with you?", "\"Yes. {D.He} met with us and answered questions about the night.\"")],
        defenseRole: "Swim team parent",
        defenseExam: [.direct("How do you know {D}?", "\"I am a swim team parent. My child swims for the club, and I see {D} at every practice and meet.\""), .direct("What did you see of the 16-year-old swimmer?", "\"Very angry at being cut. The teen stormed out of the pool one afternoon and slammed a locker.\""), .direct("Did the defendant cut the swimmer?", "\"No. The head coach did. {D.He} was an assistant and tried to calm the swimmer down.\""), .direct("Did you hear any threats?", "\"No. I never heard anyone threaten {V} or anyone else, and nothing like it from {DF}.\""), .direct("How did the defendant treat the swimmers?", "\"Kindly. {DF} stayed late to help kids with their strokes and gave rides home sometimes.\""), .direct("What did you think when you heard the charges?", "\"I could not believe it. {D.He} seemed devoted to {V}, and I never saw any sign of trouble.\""), .cross("Did you see the defendant with the 16-year-old?", "\"Often, at practice. They were close, and {DF} coached the teen.\""), .cross("Did you hear about any payments?", "\"No. I know nothing about money.\""), .cross("Did you see the defendant give the teen a ride?", "\"A few times, with other kids in the car.\""), .cross("Were you at the meet that night?", "\"Yes. {D.He} was at the meet until late, as far as I recall.\""), .cross("Are you a friend of {D}?", "\"We are friendly. I can only say what I observed at those practices.\"")],
        theory: ("{D} paid teens to kill {D.his} spouse and told them to hide it.", "A teen with a grudge made up a story to protect himself."),
        allocution: "\"I cannot say more than I have.\"",
        truths: ("{DL} gave the 16-year-old a key to the garage and told {D.him} when {V} would be there.", "The teen kept a journal that proves the idea was entirely his own."),
        defendant: [.direct("Did you plan this?", "\"No. I never planned, paid for, or asked for anyone to hurt {V}. I loved {V}.\""), .direct("Where were you that night?", "\"At a swim meet an hour away. I was with the team until late, and I drove home alone.\""), .direct("What was the $4,000?", "\"A bill for the pool fund. I withdrew it to pay a lane rental and equipment, and I have the receipts.\""), .direct("What did you mean on the wire when you said 'Say nothing and we are fine'?", "\"Say nothing to the press. Reporters were calling the families, and I wanted the teens left alone.\""), .direct("How did you feel when you found {V}?", "\"Like the world ended. I screamed and called 911, and I held {V}'s hand until help came.\""), .direct("What do you want {V}'s family to know?", "\"I loved {V}. I did not do this, and I want the person who did to be caught.\""), .cross("Two teens say you offered $4,000, don't they?", "\"They say so. They are lying, and they got deals.\""), .cross("You withdrew $4,000 the week before, didn't you?", "\"Yes, for the pool fund. I can show the receipts.\""), .cross("You told a teen to say nothing, didn't you?", "\"I meant the press. I did not mean the sheriff.\""), .cross("A new $250,000 life insurance policy was on {V}, wasn't there?", "\"Yes. We bought it together, for our future.\""), .cross("You were the first to call 911, weren't you?", "\"Yes, as soon as I got home.\"")],
        openings: ("{V}, 26, was beaten to death with a bat in the garage of the home {V} shared with {D}, {V}'s spouse. Weeks later a 16-year-old swimmer and a friend confessed and said {D} offered $4,000 and a place to stay, and a third teen's wire caught {D} urging silence.", "{D} was at a swim meet an hour away, and $4,000 paid a pool bill. Teens who confess for a deal will say what prosecutors want to hear."),
