        impact: "{V} was a good father figure to everyone at that shop.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .female, "V": .male])

    static let romanceScamV1 = SmallCases.make(
        key: "story.romanceScam",
        category: .whiteCollar,
        headlines: ["Widow Mailed $120,000 and Laptops to a Ship Captain Who Was Not Real", "Reshipping Mailbox Tied to Online Romance Fraud"],
        law: "falsePretenses100k",
        threshold: 6,
        spec: "Obtained over $100,000 by false pretenses from {V}, a victim of an online romance fraud, over several months before {DATE}.",
        ages: 24...38,
        victim: true,
        summary: "{V}, 72, a retired bus driver, met a man online who said he was a ship's captain stuck in port. Over seven months {V} mailed $120,000 in cashier's checks and four new laptops to a private mailbox for 'customs.' The mailbox was rented by {D}, who repackaged the goods and mailed them overseas, keeping a cut. {DL} says {D.he} answered a work-from-home ad for a 'package inspector.'",
        state: [E(.document, 3, "Mailbox Rental", "A private mailbox opened in {DL}'s name with {DL}'s license."), E(.digital, 3, "Shipping Records", "Forty-one parcels sent abroad on {DL}'s account, including {V}'s laptops."), E(.digital, 2, "Chat With 'Manager'", "{DL} is told to remove invoices before reshipping."), E(.document, 2, "Commission Payments", "Weekly transfers to {DL} totaling $9,600.")],
        defense: [E(.document, 2, "Job Ad and Contract", "A formal contract for a package inspector at a made-up company."), E(.statement, 1, "No Contact", "{DL} never spoke to {V}.")],
        role: "Postal inspector",
        exam: [.direct("What did the mailbox show?", "\"Checks and laptops from {V} landing there. The private mailbox was opened in {D}'s name with {DL}'s license.\""), .direct("What happened to the goods?", "\"{DL} repackaged them and shipped them abroad. Shipping records show forty-one parcels sent on {DL}'s account, including {V}'s laptops.\""), .direct("How much did {V} lose?", "\"$120,000 in cashier's checks and four new laptops over seven months. {V} was a retired bus driver, 72 years old.\""), .direct("What did the chat with the 'manager' show?", "\"It showed {DL} being told to remove invoices before reshipping. The instruction came from an account called the manager.\""), .direct("What payments did {D} receive?", "\"Weekly transfers totaling $9,600. The money came from accounts connected to the scheme.\""), .direct("Was there a contract?", "\"A fake one. It looked professional and described {D.his} role as a package inspector.\""), .cross("Did the defendant know {V}?", "\"No contact we found. {DL} never spoke to {V} that we know of.\""), .cross("Did the defendant receive the checks directly?", "\"The checks went to the mailbox, and {DL} forwarded the goods. {DL} did not deposit them.\""), .cross("Did you identify the real organizers?", "\"Not yet. They used fake names and overseas accounts, and we are still working.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} handed over the chat and the contract and explained the job.\""), .cross("Was the defendant paid regularly?", "\"Weekly, in small amounts. It looked like a part-time job.\"")],
        defenseRole: "Fraud educator",
        defenseExam: [.direct("What is your work?", "\"I am a fraud educator. I teach seniors and workers about scams and how people are recruited into them.\""), .direct("How do these schemes recruit?", "\"With fake jobs and real-looking contracts. They promise work from home and a steady paycheck.\""), .direct("Is it plausible a worker is fooled?", "\"Sometimes. Scammers build a convincing story, and workers believe they are doing legitimate shipping.\""), .direct("What do they ask workers to do?", "\"Receive packages, repackage them, and send them on, often with small tasks like removing invoices.\""), .direct("Do they usually remove invoices?", "\"Rarely by honest employers. Removing paperwork is a red flag, and workers often miss it.\""), .direct("How are workers paid?", "\"Weekly, in small amounts, to build trust. The pay looks real because it is.\""), .cross("Do some workers know what they are doing?", "\"Yes. Some do. I cannot tell which kind {D} is from the file.\""), .cross("Would a warning from a friend change things?", "\"It should. A worker told it is a scam has a duty to stop.\""), .cross("Would forty-one parcels raise questions?", "\"They might. Each parcel is another chance to ask what is going on.\""), .cross("Do you charge for your testimony?", "\"I am paid for my time, as in any case.\""), .cross("Have you met {D}?", "\"No. I reviewed the file.\"")],
        theory: ("{D} ran a reshipping mailbox for a romance scam and kept a cut.", "A fooled job seeker."),
        allocution: "\"I should have asked more questions.\"",
        truths: ("{DL} was told by a friend the job was a scam and kept shipping for three more weeks.", "{DL} reported the odd invoices to the 'company' twice and was assured they were routine."),
        defendant: [.direct("What was your job?", "\"Checking packages. I answered a work-from-home ad for a package inspector and was told to check and reship.\""), .direct("Why did you remove invoices?", "\"I was told it was a customs rule. The manager said invoices had to come off for overseas shipping.\""), .direct("What about the $9,600?", "\"My pay. I was paid weekly, and I thought it was a real wage.\""), .direct("What did you think was in the packages?", "\"Laptops and goods for customers overseas. I did not know they came from people being cheated.\""), .direct("How did you feel when you learned?", "\"Sick. I did not know {V} existed, and I am sorry for what happened.\""), .direct("What do you want {V} to know?", "\"I am deeply sorry. I thought it was a job, and I did not know you were being cheated.\""), .cross("You rented the mailbox in your name, didn't you?", "\"Yes. The job required it, and I used my license.\""), .cross("You shipped forty-one parcels, didn't you?", "\"Yes. I thought it was legitimate.\""), .cross("You removed invoices before shipping, didn't you?", "\"Yes. I was told to, and I did not question it.\""), .cross("You kept a cut of about $9,600, didn't you?", "\"Yes. It was my pay.\""), .cross("You never checked the company, did you?", "\"I looked at the contract. I should have done more.\"")],
        openings: ("{V}, 72, a retired bus driver, met someone online who claimed to be a ship's captain stuck in port and mailed $120,000 in cashier's checks and four laptops to a private mailbox rented by {D}. {D} repackaged the goods, mailed them overseas, and kept $9,600.", "{D} answered a work-from-home ad for a package inspector and followed instructions that looked like a customs rule. A worker who was used by scammers is a victim too."),
        closings: ("A mailbox in {D}'s name, forty-one parcels, removed invoices, and $9,600 in weekly pay. {D} was a link in the chain that robbed {V}.", "A fake job, a fake contract, and a manager who gave orders. The State must prove {D} knew the packages came from a scam."),
        timeline: [(-210, "{V} begins chatting online."), (-30, "{DL} rents the mailbox."), (0, "{V} mails the last check."), (60, "A bank flags the pattern.")],
        identified: "Mailbox and shipping records.",
        aggravating: ["The victim was elderly"],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

