        defenseRole: "Roommate",
        defenseExam: [.direct("Whose pills were they?", "\"Mine, from my doctor. I have a prescription for them, and I take them for focus.\""), .direct("Why did you give them to {D}?", "\"I was leaving for exams and did not want them lost. I gave them to {D} to hold for a few days.\""), .direct("Is the baggie labeled?", "\"No. I put them in a baggie when I packed, and I did not label it.\""), .direct("Why did you not keep the bottle?", "\"I needed it with me. I took the bottle and left the extra pills with {D.him}.\""), .direct("How many pills did you give the defendant?", "\"Eighteen. They were the ones I would not need during my exam week.\""), .direct("Did you ask the defendant to sell any?", "\"No. I would never. I asked {DF} to hold them.\""), .cross("Did the defendant take any?", "\"Not that I know. I did not count, and {D.he} never said so.\""), .cross("Did you tell anyone about it?", "\"No. I did not think it was a big deal.\""), .cross("Is it legal to give your prescription to someone else?", "\"No. I know that now. I made a mistake.\""), .cross("Did you tell the deputy it was yours?", "\"Yes, when they asked. I was honest.\""), .cross("Are you friends with the defendant?", "\"We are roommates. We get along, and I trusted {D.him}.\"")],
        theory: ("{D} had amphetamines with no prescription.", "{D} was holding a roommate's pills."),
        allocution: "\"I should have said no.\"",
