        defendant: [.direct("Whose pills were they?", "\"My roommate's. My roommate asked me to hold them during finals.\""), .direct("Did you take any?", "\"No. I never took any of them. I did not open the baggie.\""), .direct("Why were they unlabeled?", "\"That is how they were handed to me. The baggie was loose, and I never thought about labels.\""), .direct("Why did you forget about them?", "\"I was cramming. I had exams and papers, and I put the baggie in my gym bag and did not think of it again.\""), .direct("Why did you agree to the search?", "\"I had nothing to hide. I thought it would be quick, and I did not remember the pills.\""), .direct("What do you want the court to know?", "\"I made a mistake by agreeing to hold something that was not mine. I never sold or used them.\""), .cross("Eighteen pills were in your gym bag, weren't they?", "\"Yes. I know I should not have held them.\""), .cross("You have no prescription, do you?", "\"No. I do not.\""), .cross("You consented to the search, didn't you?", "\"Yes. I forgot about the pills.\""), .cross("You cannot show the roommate's prescription, can you?", "\"The roommate can. I do not have it.\""), .cross("The baggie was unlabeled, wasn't it?", "\"Yes. That is how I was given it.\"")],
