        state: [E(.video, 3, "Property Room Camera", "{DL} alone with the bag for six minutes."), E(.forensic, 3, "Weight Check", "A certified scale shows 22 grams less than at seizure."), E(.forensic, 2, "Resealed Tape", "Two layers of tape with a second signature.")],
