        state: [E(.forensic, 3, "Breath Test", "A reading of 0.10 at the stop."), E(.document, 3, "DMV Record", "The license was revoked for a prior DWI."), E(.statement, 1, "Store Clerk", "The clerk says {DL} stumbled and smelled of alcohol.")],
        defense: [E(.statement, 1, "Ride Fell Through", "{DL} says a ride never came.")],
        role: "Sheriff's deputy",
